use super::*;
struct WorkProducer{maximum:u64}
impl crate::OriginalWorkRecipient for WorkProducer{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:crate::OriginalWorkQuote<'reply>,observed:u64,additional:u64)->crate::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|total|total<=self.maximum)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
}
pub(super) fn with_effect<R>(grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut crate::RetainedAllocationEffect<'_>)->R)->(R,Option<usize>){
 use crate::OriginalWorkRecipient;let mut authority=crate::OriginalWorkAuthority::new(WorkProducer{maximum});let result=authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;let mut proof=None;assert_eq!(work.prepare_for_action(maximum,&mut action).unwrap(),Some(true));let mut receipt=None;work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let output={let mut effect=crate::RetainedAllocationEffect::new(grant,maximum,&mut actual,receipt.as_mut().unwrap());operation(&mut effect)};let performed=crate::OriginalWorkSink::observed_work(receipt.as_ref().unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();if performed==0{work.cancel_for_action(&mut action).unwrap()}else{let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let partial=partial.take().expect("original fixture Work partial outcome");assert_eq!(partial.total(),performed);assert!(partial.source_refusal().is_none());assert!(work.commit_for_action(performed,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}(output,actual)}).unwrap();assert!(!authority.has_live_actions());result
}

pub(super) fn complete<T,E>(poll:crate::RetainedWorkPoll<T,E>)->RetainedWorkOutcome<T,E>{match poll{crate::RetainedWorkPoll::Complete(turn)=>turn,crate::RetainedWorkPoll::Pending{..}=>panic!("expected completed original action")}}
fn put<T>(owner:&mut NativeOwnedStorage<T>,input:&mut Option<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=with_effect(grant,1,|effect|owner.put_from(input,effect));assert_eq!(actual,None);turn}
fn take<T>(owner:&mut NativeOwnedStorage<T>,output:&mut Option<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=with_effect(grant,1,|effect|owner.take_into(output,effect));assert_eq!(actual,None);turn}
fn reserve<T>(owner:&mut NativeOwnedStorage<T>,grant:RetainedCloneGrant)->crate::RetainedWorkPoll{let(turn,actual)=with_effect(grant,1,|effect|owner.reserve_empty(effect));match &turn{crate::RetainedWorkPoll::Pending{work}=>{assert_eq!(*work,0);assert_eq!(actual,None)},crate::RetainedWorkPoll::Complete(turn)=>{let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());if turn.work==0{assert_eq!(actual,None)}else if turn.result.is_err(){assert_eq!(actual,Some(0))}else if NativeOwnedStorage::<T>::reserve_demand().capacity_bytes>0{assert_eq!(actual,Some(progress.retained_capacity_bytes))}}}turn}

fn post(bank:&mut RetainedCloneGrant,fuel:&mut u128,turn:RetainedWorkOutcome)->RetainedCloneProgress{assert!(turn.work<=1);*fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;p}
#[test]
fn actual_typed_backing_is_retained_across_denial_null_initialization_and_uninitialized_cancel(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=u128::from(s["fuel"].as_u64().unwrap());let mut owner=NativeOwnedStorage::<[u64;2]>::empty();assert_eq!(NativeOwnedStorage::<[u64;2]>::reserve_demand().capacity_bytes,row["bytes"].as_u64().unwrap()as usize);
 for denied in [RetainedCloneGrant{maximum_copy_bytes:NativeOwnedStorage::<[u64;2]>::reserve_demand().copy_bytes-1,..bank},RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:15,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||reserve(&mut owner,denied));let turn=complete(turn);assert_eq!(turn.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(row["preflight"],"completedNoProgress");assert_eq!(heap,(0,0));assert!(!owner.reserved());}
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||reserve(&mut owner,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));let turn=complete(turn);assert_eq!(turn.work,u128::from(row["nullWork"].as_u64().unwrap()));fuel-=turn.work;assert_eq!(row["nullKind"],"AllocationFailed");assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert!(!owner.reserved());
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||reserve(&mut owner,RetainedCloneGrant{maximum_items:1,..bank}));let turn=complete(turn);assert_eq!(turn.work,u128::from(row["reserveWork"].as_u64().unwrap()));let p=post(&mut bank,&mut fuel,turn);assert_eq!(p.copied_bytes,NativeOwnedStorage::<[u64;2]>::reserve_demand().copy_bytes);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let address=owner.address();let mut input=Some([17,23]);let denied=put(&mut owner,&mut input,RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,0);post(&mut bank,&mut fuel,denied);assert_eq!(input,Some([17,23]));assert_eq!(owner.address(),address);assert!(owner.get().is_none());
 let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:NativeOwnedStorage::<[u64;2]>::move_demand().copy_bytes-1,..bank};let turn=put(&mut owner,&mut input,denied);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert!(input.is_some());assert!(!owner.initialized());assert_eq!(owner.address(),address);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||put(&mut owner,&mut input,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,u128::from(row["initializeWork"].as_u64().unwrap()));let p=post(&mut bank,&mut fuel,turn);assert_eq!(row["moveFields"],serde_json::json!(["optionSlot","typedBody","initializedFlag"]));assert_eq!(p.copied_bytes,NativeOwnedStorage::<[u64;2]>::move_demand().copy_bytes);assert_eq!(heap,(0,0));assert!(input.is_none());assert_eq!(owner.address(),address);assert_eq!(serde_json::to_value(owner.get().unwrap()).unwrap(),row["value"]);
 let mut output=None;let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:NativeOwnedStorage::<[u64;2]>::move_demand().copy_bytes-1,..bank};let turn=take(&mut owner,&mut output,denied);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert!(output.is_none());assert!(owner.initialized());assert_eq!(owner.address(),address);let turn=take(&mut owner,&mut output,RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn);assert_eq!(output.take(),Some([17,23]));let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||with_effect(RetainedCloneGrant{maximum_items:1,..bank},1,|effect|owner.release(effect)));assert_eq!(actual,None);assert_eq!(row["releaseFields"],serde_json::json!(["backingPointer"]));assert_eq!(turn.work,u128::from(row["releaseWork"].as_u64().unwrap()));let p=post(&mut bank,&mut fuel,turn);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(owner.terminal_is_empty());assert_eq!(with_effect(Default::default(),0,|effect|owner.release(effect)).0.work,u128::from(row["cachedWork"].as_u64().unwrap()));
 let turn=complete(reserve(&mut owner,RetainedCloneGrant{maximum_items:1,..bank}));post(&mut bank,&mut fuel,turn);assert!(owner.get().is_none());let address=owner.address();let demand=owner.release_demand();let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes-1,..bank};let(turn,actual)=with_effect(denied,1,|effect|owner.release(effect));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(owner.address(),address);let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||with_effect(RetainedCloneGrant{maximum_items:1,..bank},1,|effect|owner.release(effect)));let p=post(&mut bank,&mut fuel,turn);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(owner.terminal_is_empty());
}


#[test]
fn zero_sized_backing_prices_its_real_pointer_without_a_physical_allocation(){
 let mut owner=NativeOwnedStorage::<()>::empty();let demand=NativeOwnedStorage::<()>::reserve_demand();assert_eq!(demand.capacity_bytes,0);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||with_effect(grant,1,|effect|owner.reserve_empty(effect)));let turn=complete(turn);let progress=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(progress.copied_bytes,demand.copy_bytes);assert_eq!(progress.retained_capacity_bytes,0);assert!(owner.reserved());assert!(with_effect(grant,1,|effect|owner.release(effect)).0.result.is_ok());assert!(owner.terminal_is_empty());
}

#[test]
fn pure_receiver_seed_enters_only_the_original_paid_backing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();assert_eq!(law["seedFields"],serde_json::json!(["receiverHeader","initializedFlag"]));let mut owner=NativeOwnedStorage::<u64>::empty();let reserve_demand=NativeOwnedStorage::<u64>::reserve_demand();let mut grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:reserve_demand.copy_bytes.max(NativeOwnedStorage::<u64>::seed_demand().copy_bytes).max(NativeOwnedStorage::<u64>::move_demand().copy_bytes),maximum_capacity_bytes:reserve_demand.capacity_bytes,maximum_release_bytes:reserve_demand.capacity_bytes,maximum_depth:1};let(birth,mut actual)=with_effect(grant,1,|effect|owner.reserve_empty(effect));assert_eq!(actual,Some(reserve_demand.capacity_bytes));let birth=complete(birth);assert_eq!(birth.work,1);assert!(birth.result.is_ok());let address=owner.address();let demand=NativeOwnedStorage::<u64>::seed_demand();let mut calls=0;for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(turn,marker)=with_effect(denied,1,|effect|owner.initialize_seed(effect,||{calls+=1;Ok(17)}));actual=marker;let turn=complete(turn);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(calls,0);assert_eq!(owner.address(),address);assert!(!owner.initialized())}let(turn,marker)=with_effect(grant,1,|effect|owner.initialize_seed(effect,||{calls+=1;Ok(17)}));actual=marker;let turn=complete(turn);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert_eq!(actual,None);assert_eq!(calls,1);assert_eq!(owner.address(),address);assert_eq!(owner.get(),Some(&17));let mut output=None;assert!(take(&mut owner,&mut output,grant).result.is_ok());assert_eq!(output,Some(17));grant.maximum_release_bytes=reserve_demand.capacity_bytes;assert!(with_effect(grant,1,|effect|owner.release(effect)).0.result.is_ok());assert!(owner.terminal_is_empty());
}

#[test]
fn boxed_publication_keeps_the_exact_original_backing_and_output_slot(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();assert_eq!(law["boxPublicationFields"],serde_json::json!(["backingPointer","initializedFlag","outputBoxOption"]));let mut owner=NativeOwnedStorage::<u64>::empty();let reserve=NativeOwnedStorage::<u64>::reserve_demand();let seed=NativeOwnedStorage::<u64>::seed_demand();let publication=NativeOwnedStorage::<u64>::box_demand();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:reserve.copy_bytes.max(seed.copy_bytes).max(publication.copy_bytes),maximum_capacity_bytes:reserve.capacity_bytes,maximum_release_bytes:4096,maximum_depth:64};let(birth,actual)=with_effect(grant,1,|effect|owner.reserve_empty(effect));assert!(complete(birth).result.is_ok());assert_eq!(actual,Some(reserve.capacity_bytes));let address=owner.address().unwrap();let(seed_turn,actual)=with_effect(grant,1,|effect|owner.initialize_seed(effect,||Ok(17)));assert!(complete(seed_turn).result.is_ok());assert_eq!(actual,None);let mut output=None;let denied=RetainedCloneGrant{maximum_copy_bytes:publication.copy_bytes-1,..grant};let(poll,actual)=with_effect(denied,1,|effect|owner.take_box_into(&mut output,effect));let turn=complete(poll);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(owner.address(),Some(address));assert!(output.is_none());let(poll,actual)=with_effect(grant,1,|effect|owner.take_box_into(&mut output,effect));let turn=match poll{crate::RetainedWorkPoll::Complete(turn)=>turn,crate::RetainedWorkPoll::Pending{..}=>panic!("funded original Box publication stayed pending")};assert_eq!(turn.result.unwrap().progress().copied_bytes,publication.copy_bytes);assert_eq!(actual,None);assert!(owner.terminal_is_empty());assert_eq!(std::ptr::from_ref(output.as_ref().unwrap().as_ref())as usize,address);assert_eq!(**output.as_ref().unwrap(),17);let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(error,_)|error).unwrap();for _ in 0..10000{if close.terminal_is_empty(){break}let demand=close.next_demand(4096).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let units=close.next_computational_work(4096).unwrap();let(result,actual)=with_effect(grant,units,|effect|close.step(effect));let progress=complete(result).result.unwrap().progress();if let Some(bytes)=actual{assert_eq!(bytes,progress.retained_capacity_bytes)}}assert!(close.terminal_is_empty());
}

#[test]
fn occupied_original_marker_refuses_second_backing_before_work(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut first=NativeOwnedStorage::<u64>::empty();let mut second=NativeOwnedStorage::<u64>::empty();let d=NativeOwnedStorage::<u64>::reserve_demand();let grant=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:d.copy_bytes*2,maximum_capacity_bytes:d.capacity_bytes*2,maximum_release_bytes:d.capacity_bytes,maximum_depth:d.depth};let(((initial,refused),actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||with_effect(grant,2,|effect|{let initial=first.reserve_empty(effect);let refused=second.reserve_empty(effect);(initial,refused)}));let initial=complete(initial);let refused=complete(refused);assert!(initial.result.is_ok());assert_eq!(initial.work,1);assert_eq!(refused.work,u128::from(fixture["occupiedMarkerWork"].as_u64().unwrap()));assert!(refused.result.is_err());assert!(first.reserved());assert!(!second.reserved());assert_eq!(actual,Some(d.capacity_bytes));assert_eq!(heap,(d.capacity_bytes,0));assert!(with_effect(grant,1,|effect|first.release(effect)).0.result.is_ok());assert!(first.terminal_is_empty());
}

#[test]
fn actual_work_overrun_refuses_backing_without_replaying_or_replacing_owner(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut owner=NativeOwnedStorage::<u64>::empty();let d=NativeOwnedStorage::<u64>::reserve_demand();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()};let mut authority=crate::OriginalWorkAuthority::new(WorkProducer{maximum:1});let ((poll,actual,total,admitted,counter),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));let mut receipt=None;work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let mut counter=0;let poll={let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap());counter+=1;owner.reserve_empty(&mut effect)};let total=crate::OriginalWorkSink::observed_work(receipt.as_ref().unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let partial=partial.take().unwrap();assert!(!partial.admitted());assert!(partial.source_refusal().is_none());let mut proof=None;let admitted=work.commit_for_action(total,action,&mut proof).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();(poll,actual,total,admitted,counter)}).unwrap());let turn=complete(poll);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::WorkLimit);assert_eq!(fixture["overrunKind"],"WorkLimit");assert_eq!(total,u128::from(fixture["overrunActual"].as_u64().unwrap()));assert!(!admitted);assert_eq!(counter,1);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert!(owner.terminal_is_empty());assert!(!authority.has_live_actions());
}
